def order(graph):
    deps = {k:set(v) for k,v in graph.items()}
    for name in set().union(*deps.values()) if deps else set():
        deps.setdefault(name,set())
    result=[]
    while deps:
        ready=sorted(k for k,v in deps.items() if not v)
        if not ready:
            raise ValueError('cycle')
        name=ready[0]
        result.append(name)
        del deps[name]
        for remaining in deps.values():
            remaining.discard(name)
    return result

